import java.util.*;

public class Main {
    long toNumber(ListNode node) {
        long result = 0, place = 1;
        while (node != null) {
            result += node.val * place;                                            // each node contributes to an increasingly significant place value
            place *= 10;
            node = node.next;
        }
        return result;
    }

    ListNode addTwoNumbers(ListNode l1, ListNode l2) {
        long total = toNumber(l1) + toNumber(l2);
        ListNode dummy = new ListNode(0);
        ListNode cur = dummy;
        if (total == 0) {
            cur.next = new ListNode(0);
            return dummy.next;
        }
        while (total > 0) {
            cur.next = new ListNode((int) (total % 10));                              // peel off digits least-significant-first directly
            cur = cur.next;
            total /= 10;
        }
        return dummy.next;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        ListNode l1 = new ListNode(2, new ListNode(4, new ListNode(3)));
        ListNode l2 = new ListNode(5, new ListNode(6, new ListNode(4)));
        ListNode result = solution.addTwoNumbers(l1, l2);
        StringBuilder sb = new StringBuilder();
        while (result != null) { sb.append(result.val).append(" "); result = result.next; }
        System.out.println(sb.toString().trim());
    }
}

